// THIS IS A DARKPACK UI FILE
// place to store phone background image data
// recommended image dimensions are 400x600
// encoding in base64 is the only way i can find to make them 'local' without requiring a hard link to a file on the web
// using https://www.base64-image.de/ and converting from a webp so its the smallest possible file size
// i highly do not recommend leaving word wrap enabled while working in this file, base64 strings are LONG
export const FOREST_B64 = 'data:image/webp;base64,'
export const BEACH_B64 = 'data:image/webp;base64,'
export const SUMMERFOREST_B64 = 'data:image/webp;base64,'
export const SFCITYSCAPE_B64 = 'data:image/webp;base64,'
export const SFSTREET_B64 = 'data:image/webp;base64,'
// export const EXAMPLE = ''

// if you feel inclined to, you can link to a background image via the web, too. an example is below
//summerforest_b64: 'https://thefinalnights.com/assets/game/sunny_forest.jpg',
export const backgrounds: Record<string, string> = {
    summerforest_b64: SUMMERFOREST_B64,
    forest_b64: FOREST_B64,
    beach_b64: BEACH_B64,
    sfcityscape_b64: SFCITYSCAPE_B64,
    sfstreet_b64: SFSTREET_B64,
    //example_key: EXAMPLE,
};
